package rout

import (
	"bytes"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// Compatibility with what v0.5.0 wrote (testdata/v050 was generated by the v0.5.0 code itself).

func v050App(t *testing.T) (*App, string, []byte) {
	t.Helper()
	raw, e := os.ReadFile("testdata/v050/state.json")
	if e != nil {
		t.Fatal(e)
	}
	tok, e := os.ReadFile("testdata/v050/token.txt")
	if e != nil {
		t.Fatal(e)
	}
	a := testApp(t)
	if e = os.WriteFile(filepath.Join(a.Home, "state.json"), raw, 0600); e != nil {
		t.Fatal(e)
	}
	return a, strings.TrimSpace(string(tok)), raw
}

func TestV050StateLoadsAndRoundTripsByteForByte(t *testing.T) {
	a, _, raw := v050App(t)
	s, e := a.Load()
	if e != nil {
		t.Fatal(e)
	}
	b, e := JSON(s)
	if e != nil {
		t.Fatal(e)
	}
	if !bytes.Equal(bytes.TrimSpace(b), bytes.TrimSpace(raw)) {
		t.Fatalf("a v0.5.0 state no longer serializes to the same bytes (new fields leaked into old data?)\n%s", b)
	}
	for _, key := range []string{"via_relay", "via_address", `"chain"`, "language_variant"} {
		if strings.Contains(string(b), key) {
			t.Fatalf("a new field appeared in an old state: %s", key)
		}
	}
	if len(s.Profiles) != 4 || len(s.Exits) != 1 || len(s.Subscriptions) != 1 || s.AI == nil || !s.AI.Enabled {
		t.Fatalf("state content changed: %d profiles, %d exits, %d subscriptions, AI %+v", len(s.Profiles), len(s.Exits), len(s.Subscriptions), s.AI)
	}
}

func TestV050SubscriptionTokenAndNodeLinksStillServe(t *testing.T) {
	a, token, _ := v050App(t)
	s, _ := a.Load()
	h := newSubscriptionHandler(func() (State, error) { return s, nil }, func(string, ...any) {})
	w := get(h, "GET", "/s/"+token)
	if w.Code != 200 {
		t.Fatalf("the v0.5.0 subscription URL stopped working: %d", w.Code)
	}
	links := decodeBody(t, w.Body.String())
	if len(links) != 3 {
		t.Fatalf("subscription now lists %d links", len(links))
	}
	for i, p := range []Profile{s.Profiles[0], s.Profiles[1], s.Profiles[2]} {
		want, e := p.URI()
		if e != nil || links[i] != want {
			t.Fatalf("link %d changed: %q vs %q (%v)", i, links[i], want, e)
		}
	}
	if get(h, "GET", "/s/"+token+"x").Code == 200 {
		t.Fatal("an invalid token was accepted")
	}
	// An unrelated change keeps the token hash, the plan and the node selection.
	before := s.Subscriptions[0]
	if e := a.RenameProfile(s.Profiles[3].ID, "Renamed relay"); e != nil {
		t.Fatal(e)
	}
	after, _ := a.Load()
	if after.Subscriptions[0].TokenHash != before.TokenHash || len(after.Subscriptions[0].NodeIDs) != len(before.NodeIDs) {
		t.Fatal("an unrelated edit disturbed the subscription")
	}
	h = newSubscriptionHandler(func() (State, error) { return after, nil }, func(string, ...any) {})
	if get(h, "GET", "/s/"+token).Code != 200 {
		t.Fatal("the token stopped working after an unrelated edit")
	}
}

func TestV050AIRoutingKeepsItsMeaning(t *testing.T) {
	a, _, _ := v050App(t)
	s, _ := a.Load()
	bound, unbound := s.AI.BoundInboundIDs[0], s.Profiles[1].ID
	if route, _ := AIDecision(s, bound, "api.openai.com"); route != "ai" {
		t.Fatalf("bound node: %q", route)
	}
	if route, _ := AIDecision(s, unbound, "api.openai.com"); route != "original" {
		t.Fatalf("unbound node: %q", route)
	}
	eff, _ := Find(s.withAIRoutes(), bound)
	c, _ := serverConfig(eff, t.TempDir())
	b, _ := JSON(c)
	if !strings.Contains(string(b), `"tag": "ai-egress"`) || !strings.Contains(string(b), "198.51.100.77") {
		t.Fatalf("the AI exit of a v0.5.0 state is not rendered:\n%s", b)
	}
	// The only finding is the existing, documented plaintext-proxy warning of v0.5.0.
	st, e := a.AIStatus()
	if e != nil || st.ExitChain || len(st.Problems) != 1 || st.Problems[0] != proxySecurityWarning(s.Exits[0].Proxy) {
		t.Fatalf("status %+v %v", st, e)
	}
	// The plain exit is still usable and still refuses a chain-only kind change.
	if _, e := aiExitProxy(s, s.Exits[0], map[string]bool{}); e != nil {
		t.Fatal(e)
	}
}

// Chain exits are part of state.json and therefore of `rout backup` / `rout restore`.
func TestChainExitSurvivesBackupAndRestore(t *testing.T) {
	a := testApp(t)
	sc := newChainScene(t, a, Proxy{Protocol: "socks5", Host: "198.51.100.20", Port: 1080, Username: "chain-user", Password: "chain-secret-pw"})
	before, _ := a.Load()
	path := filepath.Join(t.TempDir(), "backup.json")
	if e := a.Backup(path); e != nil {
		t.Fatal(e)
	}
	// Restore into a different installation.
	b := testApp(t)
	if e := b.Restore(path); e != nil {
		t.Fatal(e)
	}
	after, e := b.Load()
	if e != nil {
		t.Fatal(e)
	}
	jb, _ := JSON(before)
	ja, _ := JSON(after)
	if !bytes.Equal(jb, ja) {
		t.Fatal("restored state differs from the backed-up state")
	}
	ex, e := FindExit(after, sc.exit.ID)
	if e != nil || !ex.isChain() || ex.ViaRelay != sc.relay.ID || ex.Proxy.Password != "chain-secret-pw" {
		t.Fatalf("chain exit lost in restore: %+v %v", ex, e)
	}
	if _, e = Find(after, sc.relay.ID); e != nil {
		t.Fatal("the relay of the chain was not restored")
	}
	// The restored installation renders the same AI route and protects the relay again.
	eff, _ := Find(after.withAIRoutes(), sc.nodeA.ID)
	if eff.AIRoute == nil || eff.AIRoute.Outbound == nil || eff.AIRoute.Outbound.Port != sc.relay.Port {
		t.Fatalf("AI route after restore: %+v", eff.AIRoute)
	}
	if e = b.DeleteProfiles([]string{sc.relay.ID}); e == nil {
		t.Fatal("the restored relay is not protected")
	}
}

// A restore that would leave a chain without its relay is refused, never half-applied.
func TestRestoreRefusesAChainWhoseRelayIsMissing(t *testing.T) {
	a := testApp(t)
	sc := newChainScene(t, a, Proxy{Protocol: "socks5", Host: "198.51.100.20", Port: 1080, Username: "u", Password: "p"})
	s, _ := a.Load()
	broken := removeProfile(s, sc.relay.ID)
	raw, _ := JSON(broken)
	path := filepath.Join(t.TempDir(), "broken.json")
	if e := os.WriteFile(path, raw, 0600); e != nil {
		t.Fatal(e)
	}
	b := testApp(t)
	e := b.Restore(path)
	// Either the restore refuses, or it loads and the chain fails closed (never a fallback).
	if e == nil {
		st, _ := b.Load()
		eff, _ := Find(st.withAIRoutes(), sc.nodeA.ID)
		if eff.AIRoute != nil && eff.AIRoute.Outbound != nil {
			t.Fatal("a chain without its relay produced a usable AI exit")
		}
	}
}
